-- Library lending schema (SQLite)
PRAGMA foreign_keys = ON;

CREATE TABLE books (
    id     INTEGER PRIMARY KEY,
    title  TEXT    NOT NULL UNIQUE,
    copies INTEGER NOT NULL CHECK (copies > 0)
);

CREATE TABLE members (
    id        INTEGER PRIMARY KEY,
    name      TEXT NOT NULL,
    joined_on TEXT NOT NULL CHECK (joined_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]')
);

CREATE TABLE loans (
    id          INTEGER PRIMARY KEY,
    book_id     INTEGER NOT NULL REFERENCES books(id),
    member_id   INTEGER NOT NULL REFERENCES members(id),
    borrowed_on TEXT    NOT NULL CHECK (borrowed_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    due_on      TEXT    NOT NULL CHECK (due_on >= borrowed_on),
    returned_on TEXT,
    CHECK (returned_on IS NULL OR returned_on >= borrowed_on)
);

CREATE INDEX idx_loans_book   ON loans(book_id);
CREATE INDEX idx_loans_member ON loans(member_id);
CREATE INDEX idx_loans_open   ON loans(returned_on);

